declare(strict_types=1);namespace App;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;final class Http{public static function json(ResponseInterface$r,mixed$d,int$s=200):ResponseInterface{$r->getBody()->write(json_encode($d,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES));return$r->withStatus($s)->withHeader('Content-Type','application/json');}public static function error(ResponseInterface$r,ApiException$e):ResponseInterface{return self::json($r,['error'=>['code'=>$e->errorCode,'message'=>$e->getMessage(),'fields'=>$e->fields]],$e->status);}public static function body(ServerRequestInterface$q):array{$d=$q->getParsedBody();return is_array($d)?$d:[];}public static function required(array$d,array$f):void{$bad=[];foreach($f as$x)if(!isset($d[$x])||!is_string($d[$x])||trim($d[$x])==='')$bad[$x]='required';if($bad)throw new ApiException(422,'validation_error','Invalid request data.',$bad);}public static function page(ServerRequestInterface$q):array{$p=(int)($q->getQueryParams()['page']??1);if($p<1)throw new ApiException(422,'validation_error','Invalid pagination.',['page'=>'minimum 1']);return[50,($p-1)*50];}}
